def solve_brute(a, target):
    # Linear scan stand-in for: Construct a BST from a preorder traversal
    for i, x in enumerate(a):
        if x == target:  # adapt predicate
            return i
    return -1

def solve(a, target):
    # Binary-search skeleton for: Construct a BST from a preorder traversal
    lo, hi = 0, len(a)  # half-open [lo, hi)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < target:  # adapt: predicate "too small"
            lo = mid + 1
        else:
            hi = mid
    return lo
